    pale = crayonStrokes(q, CRAYON_ANGLE, 0.05, 0.42, 0.034, 2.4, 0.0, px, 0.0) * light;
    blue = crayonStrokes(q, CRAYON_ANGLE + 0.1, 0.06, 0.36, 0.032, 3.0, 0.0, px, 101.0) * trough;
